  'JWT_SECRET',
  'DATABASE_URL',
  'SESSION_SECRET'
];

const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  console.error('❌ Missing required environment variables:', missingEnvVars.join(', '));
  process.exit(1);
}
```

---

## 🔴 Security Issues in app.js (Specific Code Review)

### 1. **Missing Input Sanitization**
```javascript
// Current validation is good, but missing comprehensive sanitization
body('name').trim().isLength({ min: 1, max: 100 })
// Missing: XSS prevention, HTML entity escaping
```

**Recommendation**: Add input sanitization middleware
```javascript
const { sanitize } = require('validator');

// Sanitization middleware
const sanitizeInput = (req, res, next) => {
  if (req.body) {
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = sanitize(req.body[key]).stripLow(); // Remove control characters
      }
    }
  }
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = sanitize(req.query[key]).stripLow();
      }
    }
  }
  next();
};

app.use(sanitizeInput);
```

---

### 2. **No Rate Limiting on Authentication Endpoints**
```javascript
// Rate limiting is applied globally, but auth endpoints need stricter limits
app.post('/login', ...)  // If you have one
```

**Recommendation**:
```javascript
// Stricter rate limiting for auth
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
  message: { error: 'Too many authentication attempts, please try again in 15 minutes' }
});

app.post('/login', authLimiter, ...)
```

---

### 3. **Missing Security Headers for API**
```javascript
// Currently using helmet, but missing some critical headers
// Missing: featurePolicy, noCache for sensitive responses
```

**Recommendation**:
