  lastGES: null,
};

let state = {
  status: "idle",   // idle | running | done | failed
  runId: null,
  params: null,
  startedAt: null,
  finishedAt: null,
  exitCode: null,
  pid: null,
  logLines: [],
  progress: { ...INITIAL_PROGRESS },
};

