    }

    try {
      // Generate new secret
      const newSecret = this.generateSecureSecret();

      // Update the secret in secrets manager
      await this.secretsManager.putSecretValue({
        SecretId: secretName,
        SecretString: JSON.stringify(newSecret)
      });

      // Update rotation schedule
      this.rotationSchedule[secretName] = now;

      console.log(`✅ Secret ${secretName} rotated successfully`);
    } catch (error) {
      console.error(`❌ Failed to rotate secret ${secretName}:`, error);
      throw error;
    }
  }

  generateSecureSecret() {
    const crypto = require('crypto');
    return {
      password: crypto.randomBytes(32).toString('base64'),
      secretKey: crypto.randomBytes(32).toString('hex'),
      createdAt: new Date().toISOString()
    };
  }
}

