// extract-env-info.js
// Run with: node extract-env-info.js > env-inventory.txt

const fs = require('fs');
const path = require('path');

function getRedactedValue(value, prefixLength = 4) {
  if (!value || value.length < 8) return '***';
  const trimmed = value.trim();
  return `${trimmed.slice(0, prefixLength)}...${trimmed.slice(-prefixLength)}`;
}

function analyzeEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmedLine = line.trim();
      if (trimmedLine.startsWith('#') || !trimmedLine.includes('=')) return;

      const [key, ...valueParts] = trimmedLine.split('=');
      const varName = key.trim();
      const value = valueParts.join('=').trim().replace(/["']/g, '');

      if (/\w/.test(value)) { // Only non-empty values
        envVars[varName] = getRedactedValue(value);
      }
    });

    return envVars;
  } catch (err) {
    console.error(`Error reading ${filePath}: ${err.message}`);
    return {};
  }
}

